 current=Path(a.current_selection).resolve();need(sha(current)==a.current_selection_sha,'current selection attestation mismatch');verify_current(json.load(open(current)));cfg=json.load(open(policy));g=report['writer']['grid'];need((g['width'],g['height'],g['step'],g['west'],g['north'])==(cfg['width'],cfg['height'],cfg['step_degrees'],-180,90),'grid mismatch');phys=R/'physical-direct-output-20261103';need(cfg['sha256']['physical_rows']==report['baseline_validation']['physical_rows_sha256']==sha(phys/'rows.u32le') and cfg['sha256']['physical_runs']==report['baseline_validation']['physical_runs_sha256']==sha(phys/'runs.u32le'),'physical source mismatch');cfg['sha256']['candidate_rows']=sha(base/'rows.u32le');cfg['sha256']['candidate_runs']=sha(base/'runs.u32le');need(cfg['sha256']['candidate_rows']==report['writer']['output_rows_sha256'] and cfg['sha256']['candidate_runs']==report['writer']['output_runs_sha256'],'candidate grid mismatch')
 cp=D/('config-draft'+a.label+'-pipeline.json');lp=D/('launch-draft'+a.label+'-pipeline.sh');out=D/('pipeline-draft'+a.label);need(not any(z.exists() for z in (cp,lp,out)),'target exists');cp.write_text(json.dumps(cfg,sort_keys=True,indent=2)+'\n');out.mkdir();script=D/'delta_divider_apply.py';helper=D/'delta_side_screen.py';need(sha(script)=='b349eafa599a20ce7bd2a80a681a00c03650b6221d934b0e2cf2eca8acbb9e98' and sha(helper)=='ff07610b96f83c1b510979df4533b1591c448d934f11d8bf653fc1f54ff944e7','rule code mismatch')
 pins={'base_report':a.base_report_sha,'base_monitor':a.base_monitor_sha,'base_reconciliation':a.base_reconciliation_sha,'candidate_rows':cfg['sha256']['candidate_rows'],'candidate_runs':cfg['sha256']['candidate_runs'],'physical_rows':cfg['sha256']['physical_rows'],'physical_runs':cfg['sha256']['physical_runs'],'divider':sha(div),'policy_template':sha(policy),'config':sha(cp),'source_snapshot':sha(s),'current_selection':sha(current),'apply_code':sha(script),'read_grid_helper':sha(helper)};manifest={'schema':'ural-divider-pipeline-input-v1','status':'prepared-not-run','label':a.label,'paths':{'base_dir':str(base),'base_monitor':str(m),'base_reconciliation':str(q),'config':str(cp),'divider':str(div),'source_snapshot':str(s),'current_selection':str(current),'output_prefix':str(out/'candidate')},'sha256':pins,'limitations':['Research output follows a selected, not independently certified, boundary and scope.','This downstream stage has distinct provenance and must not be attributed to island claims.']};(out/'input-manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n')
